import React from 'react';
import { cn } from '@/lib/utils';
import type { SiteStatus } from '@pingwatch/shared';

export interface StatusBadgeProps {
  status: SiteStatus | null | undefined;
  className?: string;
  size?: 'sm' | 'md';
}

export function StatusBadge({ status = 'unknown', className, size = 'md' }: StatusBadgeProps) {
  const currentStatus = status || 'unknown';

  const config = {
    up: {
      label: 'OPERATIONAL',
      bg: 'bg-[#00FF87]/10',
      text: 'text-[#00FF87]',
      border: 'border-[#00FF87]/30',
      dot: 'bg-[#00FF87]',
      isPulse: false,
    },
    down: {
      label: 'DOWNTIME',
      bg: 'bg-[#FF4D4F]/10',
      text: 'text-[#FF4D4F]',
      border: 'border-[#FF4D4F]/30',
      dot: 'bg-[#FF4D4F]',
      isPulse: true,
    },
    unknown: {
      label: 'UNKNOWN',
      bg: 'bg-[#F0A500]/10',
      text: 'text-[#F0A500]',
      border: 'border-[#F0A500]/30',
      dot: 'bg-[#F0A500]',
      isPulse: false,
    },
  }[currentStatus];

  return (
    <div
      className={cn(
        'inline-flex items-center gap-1.5 font-mono font-medium rounded-full border',
        size === 'sm' ? 'px-2 py-0.5 text-[11px]' : 'px-2.5 py-1 text-xs',
        config.bg,
        config.text,
        config.border,
        className
      )}
    >
      <span className="relative flex h-2 w-2">
        {config.isPulse ? (
          <>
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[#FF4D4F] opacity-75 duration-1000" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-[#FF4D4F]" />
          </>
        ) : (
          <span className={cn('inline-flex rounded-full h-2 w-2', config.dot)} />
        )}
      </span>
      <span>{config.label}</span>
    </div>
  );
}
